// 引入必要的模块
import * as forge from 'node-forge';

/**
 * Base64 解码并 URI 解码
 * @param encodedStr - 要解码的字符串
 * @returns 解码后的字符串
 */
function decodeBase64(encodedStr: string): string {
  try {
    const buffer: Buffer = Buffer.from(encodedStr, 'base64');
    return decodeURIComponent(
      Buffer.from(buffer)
        .toString('binary')
        .split('')
        .map((c: string) => `%${('00' + c.charCodeAt(0).toString(16)).slice(-2)}`)
        .join(''),
    );
  } catch (e) {
    // 如果不是有效的 Base64，返回原字符串
    return encodedStr;
  }
}

/**
 * 解密 AES-OFB 加密的十六进制字符串
 * @param encryptedHex - 加密的十六进制字符串
 * @param key - 解密密钥
 * @param iv - 初始化向量
 * @returns 解密后的字符串或 null（解密失败）
 */
function decryptAES_OFB(encryptedHex: string, key: string, iv: string): string | null {
  const decipher: forge.cipher.Cipher = forge.cipher.createDecipher('AES-OFB', key);
  decipher.start({ iv });

  // 将加密字符串转换为字节数组
  const encryptedBytes: string = forge.util.hexToBytes(encryptedHex);

  // 执行解密
  decipher.update(forge.util.createBuffer(encryptedBytes));
  const decryptionSuccess: boolean = decipher.finish();

  if (decryptionSuccess) {
    const decrypted: string = decipher.output.toString();
    console.log('解密成功:', decrypted);
    return decrypted;
  } else {
    console.error('解密失败');
    return null;
  }
}

/**
 * 解密器类，封装了解码和解密功能
 */
export class Decryptor {
  private key: string;
  private iv: string;

  /**
   * 创建一个解密器实例
   * @param rawKey - 密钥的 ASCII 码数组
   * @param ivArray - 初始化向量的 ASCII 码数组
   */
  constructor(rawKey: number[], ivArray: number[]) {
    this.key = String.fromCharCode(...rawKey);
    this.iv = String.fromCharCode(...ivArray);
  }

  /**
   * 解码并解密给定的加密字符串
   * @param encryptedHex - 加密的十六进制字符串
   * @returns 解密后的字符串或 null（解密失败）
   */
  public decrypt(encryptedHex: string): string | null {
    return decryptAES_OFB(encryptedHex, this.key, this.iv);
  }

  /**
   * 解码 Base64 字符串
   * @param index - 编码字符串的索引
   * @param encodedStrings - 编码字符串数组
   * @returns 解码后的字符串
   */
  public decode(index: number, encodedStrings: string[]): string {
    const decoded: string = decodeBase64(encodedStrings[index]);
    return decoded;
  }
}


